import React, { useEffect, useState } from 'react';
import { useClassFramework } from '../contexts/ClassFrameworkContext';
import { ClassNote } from '../types/ClassFramework';

interface FloatingTooltipProps {
  className?: string;
}

export function FloatingTooltip({ className = '' }: FloatingTooltipProps) {
  const [position, setPosition] = useState({ top: 100, left: 100 });
  const [hoveredElement, setHoveredElement] = useState<string | null>(null);
  const { getClassNote } = useClassFramework();

  // Track mouse movement and hovered elements
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      setPosition({ top: e.clientY - 50, left: e.clientX + 20 });
      
      // Check if we're hovering over an element with a class note
      const target = e.target as HTMLElement;
      if (target) {
        // Look for elements with class-note-* classes
        const classNoteElement = target.closest('[class*="class-note-"]');
        if (classNoteElement) {
          const classes = classNoteElement.className.split(' ');
          const classNoteClass = classes.find(cls => cls.startsWith('class-note-'));
          if (classNoteClass) {
            const noteId = classNoteClass.replace('class-note-', '');
            setHoveredElement(noteId);
            return;
          }
        }
        setHoveredElement(null);
      }
    };

    document.addEventListener('mousemove', handleMouseMove);
    return () => document.removeEventListener('mousemove', handleMouseMove);
  }, []);

  // Get the class note for the hovered element
  const classNote = hoveredElement ? getClassNote(hoveredElement) : null;

  // Don't show tooltip if no element is hovered
  if (!hoveredElement || !classNote) {
    return null;
  }

  return (
    <div 
      className="simulation-controls dark-mode"
      style={{
        position: 'fixed',
        top: position.top,
        left: position.left,
        background: 'rgba(45, 45, 45, 0.95)',
        border: '3px solid #007bff',
        borderRadius: '12px',
        padding: '1.5rem',
        zIndex: 99999,
        boxShadow: '0 8px 32px rgba(0,0,0,0.3)',
        backdropFilter: 'blur(10px)',
        minWidth: '300px',
        maxWidth: '400px',
        cursor: 'default',
        userSelect: 'auto',
        transition: 'box-shadow 0.2s',
        pointerEvents: 'auto',
        isolation: 'isolate'
      }}
    >
      <div 
        style={{ 
          textAlign: 'center', 
          marginBottom: '1rem',
          borderBottom: '2px solid #007bff',
          paddingBottom: '0.5rem',
          cursor: 'default',
          userSelect: 'none',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          pointerEvents: 'auto',
          position: 'relative',
          zIndex: 99999
        }}
      >
        <div style={{ flex: 1 }}>
          <h3 style={{ 
            margin: 0, 
            color: '#007bff', 
            fontSize: '1.2rem',
            fontWeight: 'bold',
            pointerEvents: 'none'
          }}>
            🎓 {classNote.title}
          </h3>
          <div style={{ 
            fontSize: '0.9rem', 
            color: '#b0b0b0',
            marginTop: '0.25rem',
            pointerEvents: 'none'
          }}>
            {classNote.category}
          </div>
        </div>
      </div>

      <div style={{ 
        fontSize: '1rem', 
        color: '#ffffff',
        lineHeight: '1.5'
      }}>
        <p style={{ marginBottom: '1rem' }}>{classNote.description}</p>
        
        {classNote.context && (
          <div style={{ 
            background: 'rgba(0, 123, 255, 0.1)', 
            border: '1px solid #007bff',
            borderRadius: '8px',
            padding: '0.75rem',
            marginTop: '0.75rem'
          }}>
            <div style={{ 
              fontSize: '0.9rem', 
              color: '#007bff',
              fontWeight: 'bold',
              marginBottom: '0.5rem'
            }}>
              Real-World Context:
            </div>
            <div style={{ fontSize: '0.9rem', color: '#b0b0b0' }}>
              {classNote.context}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
